    async def create_hook(
        self,
        co: str,
        *,
        name: str,
        id_path: str | None | Omit = omit,
        signature_header: str | Omit = omit,
        signature_secret: str | None | Omit = omit,
        request_options: RequestOptions | None = None,
    ) -> AutomationHookWithToken:
        """Завести хук

        Только тому, у кого есть chat.use (ИИ-бухгалтер): хук может питать сценарий с ИИ, а токен видит только заводящий; без права — 403 permission_error, code missing_permission, permission chat.use. Токен приёма — только в этом ответе; потерянный меняется через rotate. Повтор с тем же Idempotency-Key отдаёт тот же хук без токена (token: null). Сколько хуков у компании — предел настройки automations (hooks_per_company), сверх — 429.

        Idempotency-Key: повтор с тем же ключом и тем же телом отдаёт прежний ответ (статус и тело) с заголовком Idempotent-Replayed: true и ничего не делает второй раз; тот же ключ с другим адресом или телом — 422 (error.code = idempotency_key_reused); первый запрос с этим ключом ещё идёт — 409 (error.code = idempotency_in_progress). Запоминается только удачный ответ (2xx): после отказа повтор с тем же ключом выполнится заново. Ключ живёт сутки (настройка idempotency.keys), область — организация и тот, кто прислал (ключ API или человек).

        Доступ: automations.manage | company.manage.

        Доступно по ключу API.

        Args:
            co: id компании, co_… — из GET /v1/companies
            name: Название хука для людей (1–200 знаков): откуда приходят события.
            id_path: Путь через точку к id события в JSON тела — номер платежа или чека у отправителя. Задан и поле есть — повтор с тем же id считается тем же событием, даже с новым Idempotency-Key. null или нет — id берётся из заголовка Idempotency-Key, затем X-Event-Id, иначе — хеш тела; вдобавок то же тело в окне automations.queue.hook_dedupe_minutes (по умолчанию сутки) считается повтором. Хук, питающий сценарий с автоодобрением, обязан иметь id_path: снять его нельзя (400), а сменить может только тот, у кого есть proposals.approve (иначе 403). В 1С само пишется только событие, номер которого взят из тела по id_path; нет id_path у хука или поля в теле (номер из заголовка) — предложения ждут человека.
            signature_header: Имя заголовка с подписью: латиница, цифры, дефис, до 64 знаков; приводится к нижнему регистру. Не передан при заведении — `x-signature`.
            signature_secret: Секрет подписи (16–500 знаков), общий с отправителем. Задан — каждое событие обязано нести в заголовке signature_header HMAC-SHA256(секрет, сырое тело) в hex (можно с приставкой `sha256=`), иначе приём отвечает 401. Хранится зашифрованным и обратно не отдаётся — в ответах видно только signed. null или не передан — без подписи (при изменении null снимает подпись). По событиям хука без подписи автоодобрение ничего в 1С не пишет.
            request_options: Per-request timeout, retries, headers and idempotency key.
        """
        return await self._client.request(
            RequestSpec(
                method="POST",
                path=f"/v1/companies/{path_segment('co', co)}/automations/hooks",
                body=json_body(
                    {
                        "id_path": id_path,
                        "name": name,
                        "signature_header": signature_header,
                        "signature_secret": signature_secret,
                    }
                ),
                idempotency_header="Idempotency-Key",
            ),
            cast_to=AutomationHookWithToken,
            options=request_options,
        )

