    async def create_scenario(
        self,
        co: str,
        *,
        name: str,
        trigger: params.AutomationScenarioInputTrigger,
        action: params.AutomationScenarioInputAction | Omit = omit,
        auto_approve: params.AutomationScenarioInputAutoApprove | None | Omit = omit,
        enabled: bool | Omit = omit,
        instruction: str | Omit = omit,
        output: Mapping[str, params.AutomationOutputField] | None | Omit = omit,
        steps: Sequence[params.AutomationStep] | Omit = omit,
        request_options: RequestOptions | None = None,
    ) -> AutomationScenarioSaved:
        """Завести сценарий

        Сценарий с ИИ (action: agent) сохраняет тот, у кого есть chat.use; правило автоодобрения — тот, у кого есть proposals.approve; ключ API с пределами записи — только не шире своих пределов (видов и потолков), иначе 403 с error.code = key_write_limit. Сохранённый ключом сценарий и при запуске пишет в 1С сам только в пределах этого ключа на тот момент; отозванный ключ — не запускается. Запуск идёт от имени сохранившего. Сколько сценариев у компании — предел настройки automations (scenarios_per_company), сверх — 429.

        Idempotency-Key: повтор с тем же ключом и тем же телом отдаёт прежний ответ (статус и тело) с заголовком Idempotent-Replayed: true и ничего не делает второй раз; тот же ключ с другим адресом или телом — 422 (error.code = idempotency_key_reused); первый запрос с этим ключом ещё идёт — 409 (error.code = idempotency_in_progress). Запоминается только удачный ответ (2xx): после отказа повтор с тем же ключом выполнится заново. Ключ живёт сутки (настройка idempotency.keys), область — организация и тот, кто прислал (ключ API или человек).

        Доступ: automations.manage | company.manage.

        Доступно по ключу API.

        Args:
            co: id компании, co_… — из GET /v1/companies
            name: Название сценария (1–200 знаков).
            trigger: Когда запускать: по событию хука, по расписанию, по событию внутри Tungo или только вручную. Вид — в kind.
            action: Старая форма — один шаг (вместо него можно steps). Что делать при запуске. `agent` (по умолчанию) — ход ИИ-бухгалтера по поручению instruction: ИИ разбирает событие и данные 1С и готовит предложения — документы для записи в 1С; расход ИИ оплачивается как обычный. `checks` — проверки учёта компании (без ИИ и без предложений; находки — в ленте). `directbank` — опрос выписки DirectBank из живой 1С (без ИИ, нужно право proposals.create): предложения ложатся выпиской дня. Сам Tungo выписку не опрашивает — только этим сценарием или POST …/statements/directbank.
            auto_approve: Правило автоодобрения — только у сценария с шагом agent (action: agent или шаг agent в steps); сохраняет только тот, у кого есть proposals.approve. null или нет — всё подготовленное ждёт решения человека.
            enabled: Включён ли (по умолчанию true). Выключенный не запускается ни событием, ни по расписанию; вручную (…/run) — запускается.
            instruction: Старая форма — поручение единственного шага. Поручение ИИ обычными словами. Для action: agent обязательно (длина — не больше настройки платформы instruction_max_chars); для checks и directbank не нужно.
            output: Старая форма — итог единственного шага. Форма итога — только для action: agent. ИИ в конце хода отдаёт итог в этой форме, он приходит в запуске (output) и в вебхуке automation.run.completed — например, чтобы CRM закрыла заказ. null или нет — итог только текстом (answer).
            steps: Цепочка шагов (1–5) вместо action, instruction и output — передайте что-то одно. Пример «каждое утро»: `[{"action":"directbank"},{"action":"agent","instruction":"Разнеси выписку","when":"previous_created_proposals"},{"action":"checks"},{"action":"notify","when":"checks_found_issues"}]`. Каждый шаг agent — отдельный платный ход ИИ: запуск стоит до 5 ходов. Правило автоодобрения применяется после каждого шага agent.
            request_options: Per-request timeout, retries, headers and idempotency key.
        """
        return await self._client.request(
            RequestSpec(
                method="POST",
                path=f"/v1/companies/{path_segment('co', co)}/automations/scenarios",
                body=json_body(
                    {
                        "action": action,
                        "auto_approve": auto_approve,
                        "enabled": enabled,
                        "instruction": instruction,
                        "name": name,
                        "output": output,
                        "steps": steps,
                        "trigger": trigger,
                    }
                ),
                idempotency_header="Idempotency-Key",
            ),
            cast_to=AutomationScenarioSaved,
            options=request_options,
        )

